"use strict";(self.webpackChunkportfolio=self.webpackChunkportfolio||[]).push([["8340"],{4598(e){e.exports=JSON.parse('{"tag":{"label":"Keycloak","permalink":"/portfolio/projects/tags/keycloak","allTagsPath":"/portfolio/projects/tags","count":3,"items":[{"id":"work-projects/deploy-center/index","title":"DeployCenter - Multi-Tenant Kubernetes Deployment Platform","description":"Deployment platform I built for 20+ customer apps across 3 AWS regions. It cut per-app deploy time from 15 minutes to 3. I make batch changes from Git, developers deploy from a web dashboard, and both paths run the same Python orchestrator.","permalink":"/portfolio/projects/work-projects/deploy-center/"},{"id":"side-projects/horizon-social-network/index","title":"Horizon Social Network - Microservices Backend","description":"A Go backend for a campus social network, built for a university workshop project. Two microservices on Kubernetes behind the Istio service mesh, with Keycloak login tokens checked at the entry gateway, mTLS between services, MongoDB for posts, Neo4j for the follower graph, and container images under 10MB.","permalink":"/portfolio/projects/side-projects/horizon-social-network/"},{"id":"work-projects/observability/index","title":"Kubernetes Observability Stack","description":"Monitoring and alerting stack I built for production Kubernetes on AWS EKS. It cut mean time to resolve incidents (MTTR) by 50%, log storage cost by 70%, and alert volume by 60%, with Prometheus, Loki, Grafana OnCall, and external HTTPS probes.","permalink":"/portfolio/projects/work-projects/observability/"}],"unlisted":false}}')}}]);